import{z as o,x as s,o as A,c as d,q as r,j as l,D as e,d as a,s as n,S as i,b as B}from"./chunks/framework.C8m1ZpeB.js";const c=JSON.parse('{"title":"ML 审计","description":"","frontmatter":{"title":"ML 审计","date":"2026-09-18T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/fml-audit.md","filePath":"quant/fml-audit.md","lastUpdated":1791063341000}'),m={name:"quant/fml-audit.md"};function C(p,E,D,u,F,f){const t=s("Mermaid");return A(),d("div",null,[E[2]||(E[2]=r('<h1 id="ml-审计" tabindex="-1">ML 审计 <a class="header-anchor" href="#ml-审计" aria-label="Permalink to &quot;ML 审计&quot;">​</a></h1><div class="epigraph"><p>有效挑战不是礼貌性的异议，是有权访问、有权否定的独立复现；审计因此是工程约束，不是归档义务。</p><footer>—— 据 Board of Governors of the Federal Reserve System, SR 11-7: Supervisory Guidance on Model Risk Management, 2011 整理</footer></div><p><a href="/quant/fml-drift-management">上一课</a>给漂移装了分流器，重训、降仓、停机都要求留痕。缺口：留痕给谁看、凭什么信——审计不是事后补文档，而是让「该被信任」变成可检验的工程约束。<a href="/quant/sr-11-7-model-risk">SR 11-7 模型风险管理</a>立了三支柱与有效挑战，<a href="/quant/model-risk-inventory">模型风险清单</a>立了清单口径。本课把它们落到 ML：审计包里装什么、验证人复现什么、审计约束怎么反过来改工程。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>ML 给传统审计添了三类困难。复现链长：一个模型等于数据快照、特征定义、标签契约、切分、超参与种子的连乘，任何一环的哈希缺失，复现即失败——而传统模型的「模型」两个字就够定位。行为空间大：传统审计问「假设对不对」，ML 还要问「在哪些区域它会怎么错」——外推区、类别失衡区、各体制下的行为，没有一张地图就没有可审的对象。变更更快：逐日更新的在线模型没有「一个版本」，审计对象必须改成版本流加更新规则。审计若后置，事后重建血缘的成本随系统规模膨胀，且永远补不齐当时的口径——重建出来的不是证据，是回忆。</p><p><span class="marginnote">术语翻译：「复现链」就是把「这个数字怎么来的」拆成数据快照、特征定义、标签契约、切分、超参与种子六个环。链式结构意味着任何一环的哈希缺失，整条链就断——这与传统模型「报出模型名就能定位」完全不同。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>审计包按「边建边装」的规则组织，前九课的每份契约都是其中一节：数据血缘与三元哈希（<a href="/quant/fml-feature-store-deep">特征存储</a>）、标签四元组、\\(N\\) 台账与协议文档、切分参数与路径分布、解释口径与消融验证、监控状态机与衰减预算。装订规则只有两条：全部随模型哈希不可变存档；用途变更触发重新验证——同一套参数换个用途就是<a href="/quant/model-risk-inventory">清单</a>里的新条目。独立验证做三件事：独立复现，验证人从原始数据出发重建一次结果；概念审查，审假设、代理变量与泄漏面，包括桌下尝试是否可能逃逸出台账；结果分析，对照基准与失败案例读表现。验证人的权限写进治理：读权限到原始数据层，否定权落在晋升流程上——不通过则不得上线。</p>',8)),(A(),l(i,null,{default:e(()=>[n(t,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20PKG%5B%22%E5%AE%A1%E8%AE%A1%E5%8C%85%EF%BC%9A%E8%A1%80%E7%BC%98%E3%80%81%E6%A0%87%E7%AD%BE%E3%80%81%E5%8F%B0%E8%B4%A6%E3%80%81%E5%88%87%E5%88%86%E3%80%81%E8%A7%A3%E9%87%8A%E3%80%81%E7%9B%91%E6%8E%A7%22%5D%20--%3E%20REPRO%5B%22%E7%8B%AC%E7%AB%8B%E5%A4%8D%E7%8E%B0%EF%BC%9A%E4%BB%8E%E5%8E%9F%E5%A7%8B%E6%95%B0%E6%8D%AE%E9%87%8D%E5%BB%BA%22%5D%0A%20%20PKG%20--%3E%20CONC%5B%22%E6%A6%82%E5%BF%B5%E5%AE%A1%E6%9F%A5%EF%BC%9A%E5%81%87%E8%AE%BE%E4%B8%8E%E6%B3%84%E6%BC%8F%E9%9D%A2%22%5D%0A%20%20PKG%20--%3E%20PERF%5B%22%E7%BB%93%E6%9E%9C%E5%88%86%E6%9E%90%EF%BC%9A%E5%9F%BA%E5%87%86%E4%B8%8E%E5%A4%B1%E8%B4%A5%E6%A1%88%E4%BE%8B%22%5D%0A%20%20REPRO%20--%3E%20VERD%7B%22%E6%9C%89%E6%95%88%E6%8C%91%E6%88%98%E7%BB%93%E8%AE%BA%22%7D%0A%20%20CONC%20--%3E%20VERD%0A%20%20PERF%20--%3E%20VERD%0A%20%20VERD%20--%3E%7C%22'%E9%80%9A%E8%BF%87'%22%7C%20REG%5B%22%E6%99%8B%E5%8D%87%E7%99%BB%E8%AE%B0%EF%BC%9A%E5%93%88%E5%B8%8C%E4%B8%8E%E7%94%A8%E9%80%94%22%5D%0A%20%20VERD%20--%3E%7C%22'%E4%B8%8D%E9%80%9A%E8%BF%87'%22%7C%20BLOCK%5B%22%E9%98%BB%E6%96%AD%E4%B8%8A%E7%BA%BF%EF%BC%8C%E5%9B%9E%E5%B7%A5%E7%A8%8B%22%5D%0A%20%20REG%20--%3E%7C%22'%E7%94%A8%E9%80%94%E5%8F%98%E6%9B%B4%E6%88%96%E9%87%8D%E5%A4%A7%E6%9B%B4%E6%96%B0'%22%7C%20REVAL%5B%22%E9%87%8D%E6%96%B0%E9%AA%8C%E8%AF%81%22%5D%0A"})]),fallback:e(()=>[...E[0]||(E[0]=[a(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=B("h2",{id:"机制",tabindex:"-1"},[a("机制 "),B("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[4]||(E[4]=B("p",null,[a("审计为什么必须前置：记录与重建的成本不对称——上线时多写一行哈希，事后免一次考古；特征店的版本、协议的台账、模型的日快照，表面是研究设施，实质是为审计而建的组件。有效挑战的制度设计比清单更重要：挑战者的考核不能挂在被审模型的绩效上，否则独立是名义的；只给报告不给数据的挑战，是把仪式写进了流程。相称性原则调节深度而不删除义务：执行参数模型与组合级信号模型分档审计，但厂商模型、小型模型、以及「只是内部用用」的模型都不豁免登记——SR 11-7 对这几类的措辞是明确的。审计也不担保模型正确：它担保的是错误的成本可追溯、可归责、可关闭，这与"),B("a",{href:"/quant/model-risk-inventory"},"模型风险清单"),a("「每个条目可关闭」的口径一致。")],-1)),(A(),l(i,null,{default:e(()=>[n(t,{id:"mermaid-29",class:"mermaid",graph:"flowchart%20TD%0A%20%20Q%5B%22%E5%AE%A1%E8%AE%A1%E4%BD%95%E6%97%B6%E4%BB%8B%E5%85%A5%EF%BC%9F%22%5D%20--%3E%20F1%5B%22%E5%89%8D%E7%BD%AE%EF%BC%9A%E8%BE%B9%E5%BB%BA%E8%BE%B9%E8%A3%85%22%5D%0A%20%20F1%20--%3E%20C1%5B%22%E4%B8%8A%E7%BA%BF%E6%97%B6%E5%A4%9A%E5%86%99%E4%B8%80%E8%A1%8C%E5%93%88%E5%B8%8C%22%5D%0A%20%20C1%20--%3E%20B1%5B%22%E4%BA%8B%E5%90%8E%E5%85%8D%E8%80%83%E5%8F%A4%EF%BC%9A%E8%A1%80%E7%BC%98%E5%BD%93%E5%9C%BA%E5%8F%AF%E6%9F%A5%22%5D%0A%20%20Q%20--%3E%20F2%5B%22%E5%90%8E%E7%BD%AE%EF%BC%9A%E4%BA%8B%E5%90%8E%E8%A1%A5%E6%96%87%E6%A1%A3%22%5D%0A%20%20F2%20--%3E%20C2%5B%22%E9%87%8D%E5%BB%BA%E8%A1%80%E7%BC%98%E6%88%90%E6%9C%AC%E9%9A%8F%E7%B3%BB%E7%BB%9F%E8%A7%84%E6%A8%A1%E8%86%A8%E8%83%80%22%5D%0A%20%20C2%20--%3E%20B2%5B%22%E5%BE%97%E5%88%B0%E7%9A%84%E6%98%AF%E5%9B%9E%E5%BF%86%EF%BC%8C%E4%B8%8D%E6%98%AF%E8%AF%81%E6%8D%AE%22%5D%0A"})]),fallback:e(()=>[...E[1]||(E[1]=[a(" Loading... ",-1)])]),_:1})),E[5]||(E[5]=r('<p><span class="marginnote">直觉类比：审计包像飞机的「黑匣子 + 随机文件」，要害在于随机文件随每次飞行（每个模型版本）同步更新；等出事后再凭记忆补写飞行日志，监管不会认——补出来的叙事无法自证当时为真。</span></p><p><span class="marginnote">复现测试的最小集：每季度随机抽一个历史模型哈希，由验证人从原始数据重建训练与折外分数，误差超出浮点容差即判失败。跑不过的血缘缺口当场暴露，而不是等监管检查或事故复盘时才暴露。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>SR 11-7 三支柱的原文结构与机器学习条款已有专课，本课只做工程映射。审计不评价策略该不该存在——那是<a href="/quant/fml-model-selection-protocol">协议</a>与投委会的事；各地区监管对模型治理的具体条文是全球市场制度课程的对象；多人协作下的评审流程与知识沉淀归下一课的工作流。也别把审计包当保险箱：它的价值在被反复读取——季度复现、事故溯源、交接培训——只写不读的审计包，等于把回忆又存了一遍。</p><p><span class="marginnote">常见误区：把「小模型」「内部工具」当成豁免理由。SR 11-7 的相称性原则调节的是审计深度，不是是否登记——一个只算债券久期的小脚本，只要进了投研流程，就是清单上需要「可关闭」的条目。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>ML 审计的三个新对象：复现链、行为地图、版本流；后置审计重建的是回忆不是证据。</li><li>审计包由前九课的契约装订而成，随模型哈希不可变存档，用途变更触发重验。</li><li>独立验证三件事：复现、概念审查、结果分析；验证人有数据访问权与晋升否定权。</li><li>可审计性是架构需求：哈希、台账、快照都是为审计而建的组件。</li><li>出处：Federal Reserve SR 11-7 / OCC 2011-12, 2011；Sculley et al., <em>NeurIPS</em>, 2015（Hidden Technical Debt in Machine Learning Systems）。</li></ul>',7))])}const _=o(m,[["render",C]]);export{c as __pageData,_ as default};
